using BindOpen.Tests;
using DeepEqual.Syntax;
using NUnit.Framework;
using System.IO;

namespace BindOpen.Data.Schema;

/// <summary>
/// Contains unit tests for XML serialization and deserialization of <see cref="IBdoSchema"/>
/// instances via <see cref="SchemaDto"/> conversion.
/// </summary>
/// <remarks>
/// These tests verify that schema definitions generated by <see cref="BdoSchemaFaker"/> can be
/// mapped to DTOs, persisted to XML files on disk, and reloaded back into domain objects without losing
/// structural or property equality.
/// </remarks>
[TestFixture]
public class SchemaXmlTests
{
    private readonly string _filePath_xml = DataTestData.WorkingFolder + "Schema.xml";

    private IBdoSchema _schema;

    /// <summary>
    /// Cleans up any leftover XML output file and initializes a faked <see cref="IBdoSchema"/>
    /// instance using <see cref="BdoSchemaFaker"/> before any tests in this fixture are executed.
    /// </summary>
    [OneTimeSetUp]
    public void OneTimeSetUp()
    {
        File.Delete(_filePath_xml);

        _schema = BdoSchemaFaker.CreateSpecWithReference();
    }

    /// <summary>
    /// Determines whether two <see cref="IBdoSchema"/> instances are non-null and deeply equal.
    /// </summary>
    /// <param name="spec1">The first schema instance to compare.</param>
    /// <param name="spec2">The second schema instance to compare.</param>
    /// <returns><c>true</c> if both schemas are non-null and deeply equal; otherwise, <c>false</c>.</returns>
    public static bool Equals(
        IBdoSchema spec1,
        IBdoSchema spec2)
    {
        var b = spec1 != null && spec2 != null
            && spec1.IsDeepEqual(spec2);
        return b;
    }

    /// <summary>
    /// Verifies that the test <see cref="IBdoSchema"/> instance converts to a
    /// <see cref="SchemaDto"/> and saves cleanly to an XML file on disk.
    /// </summary>
    [Test]
    public void SaveXmlTest()
    {
        var isSaved = _schema.ToDto().SaveXml(_filePath_xml);
        Assert.That(isSaved, Is.True, "Schema saving failed.");
    }

    /// <summary>
    /// Verifies that the saved XML file loads back into a <see cref="SchemaDto"/>,
    /// converts to a POCO via <c>ToPoco()</c>, and matches the original <see cref="IBdoSchema"/>.
    /// </summary>
    [Test]
    public void LoadXmlTest()
    {
        if (_schema == null || !File.Exists(_filePath_xml))
        {
            SaveXmlTest();
        }

        var schema = XmlHelper.LoadXml<SchemaDto>(_filePath_xml).ToPoco();
        Assert.That(Equals(schema, _schema), Is.True, "Loaded schema does not match the original schema.");
    }
}